// Garde-fou : WF0 ne doit tourner qu'une seule fois.
// Si le projet IT contient déjà des incidents, on s'arrête sans rien créer.
const trouves = $input.all().flatMap(({ json }) => json.issues || []);
if (trouves.length > 0) {
  throw new Error(`Le projet IT contient déjà des incidents (par exemple ${trouves[0].key}) : WF0 s'arrête pour ne pas créer de doublons. Supprimez-les dans Jira avant de relancer.`);
}
return [{ json: { ok: true } }];

// Les 3 CI de la démo, créés comme composants du projet Jira IT.
// (Un composant déjà existant renvoie une erreur 400 : elle est ignorée, c'est voulu.)
return ['ERP-PROD', 'NAS-FICHIERS', 'MAIL-EXCH-01'].map((name) => ({ json: { name } }));

// Jeu de données de démo : 3 familles d'incidents récurrents + 4 incidents de bruit.
// Le CI est un composant Jira (créé juste avant par le nœud « Créer le composant »).
const CI = {
  erp: 'ERP-PROD',
  partage: 'NAS-FICHIERS',
  mail: 'MAIL-EXCH-01',
};

const familles = [
  { ci: CI.erp, cat: 'software', textes: ['Lenteurs ERP en fin de mois',
    'ERP très lent sur la saisie des commandes', 'Temps de réponse ERP dégradé'] },
  { ci: CI.partage, cat: 'hardware', textes: ['Partage réseau inaccessible',
    'Accès refusé au partage réseau', 'Partage réseau déconnecté'] },
  { ci: CI.mail, cat: 'network', textes: ["Mails bloqués en file d'attente",
    'Mails non distribués', 'Retards de distribution des mails'] },
];
const bruit = ['Imprimante en panne au 2e étage', 'Mot de passe expiré',
  'Écran noir au démarrage', 'Licence Office à renouveler'];

const out = [];
for (const f of familles) {
  for (let i = 0; i < 6; i++) {
    out.push({ json: { summary: f.textes[i % 3], category: f.cat, ci: f.ci } });
  }
}
for (const t of bruit) out.push({ json: { summary: t, category: 'inquiry', ci: '' } });
return out;
